@pytest.mark.parametrize('saved_answers', [False, True]) def test_real_pdf_52_pages_fit_batched_and_five_notes_reused(tmp_path, build_session, saved_answers): assert shutil.which('pdftotext'), 'Run this course test in WSL with poppler-utils installed' source = MATERIALS / '公开任务/题目1' repo = tmp_path / 'repo' repo.mkdir() for name in ('paper.pdf', 'paper.json', 'read_pdf.py', 'report.json'): shutil.copy2(source / 'repo' / name, repo / name) task = (source / 'task.md').read_text(encoding='utf-8') session, context, agent, model = build_session('paper', repo, task) session.invoke('read_file', {'path': 'report.json'}) session.invoke('read_pdf', {'start_page': 1, 'end_page': 52}) page_ids = [eid for eid, e in session.evidence.items.items() if e.page] assert len(page_ids) == 52 assert sum(len(session.evidence.items[eid].text) for eid in page_ids) > 100000 session.evidence.recall(page_ids) seen = set() sizes = [] full_notes_before_last_page = False for number in range(1, 36): messages = context.build(agent.memory, model) sizes.append(model.estimate(messages)) body = {'messages': [m.dict() for m in messages]} session.evidence.mark_exposed(body, response(code('print(1)')), number) seen |= session.evidence.current # A successful reading action advances to new pages without a per-page # note gate. Only the final five topic notes are required by the course. delivered_pages = {eid for eid in session.evidence.current if eid in page_ids} assert delivered_pages agent.memory.steps.append(ActionStep( step_number=number, timing=Timing(start_time=0, end_time=1), code_action='print("Read this PDF batch.")', observations='Read this PDF batch.')) if number % 2 == 0: topic = session.contract.topics[(number // 2 - 1) % 5] content = ('Model note for ' + topic + '; keep observed claims and evidence locators. ').ljust(1500, '.') session.evidence.last_response = response(code(f'write_note(content={content!r})')) # One observed page grounds this note; other pages do not need a # per-page acknowledgement before the next original batch advances. session.invoke('write_note', {'title': topic, 'section': topic, 'content': content, 'evidence_ids': [sorted(delivered_pages)[0]]}) if len(session.evidence.notes) == 5 and not set(page_ids).issubset(seen): full_notes_before_last_page = True if saved_answers and not session.evidence.answers: from course_agent.evidence import PAPER_QUESTIONS eid = next(eid for eid in sorted(session.evidence.exposed) if session.evidence.items[eid].page and len(session.evidence.items[eid].text.strip()) >= 20) item = session.evidence.items[eid] quote = item.text.strip()[:100] for section, questions in PAPER_QUESTIONS.items(): session.evidence.save_section(section, 'synthetic summary', 'synthetic application') for question, kind in questions.items(): value = ['synthetic'] if kind is list else 1 if kind is int else 'synthetic' session.evidence.save_answer(section, question, value, eid, item.page, quote) if set(page_ids).issubset(seen): break assert set(page_ids).issubset(seen), {'missing': len(set(page_ids) - seen), 'sizes': sizes} assert full_notes_before_last_page, 'Exercise remaining originals with all five maximum-size notes retained' > assert number <= 30, 'Reserve at least ten requests for setup, report delivery and verification' E AssertionError: Reserve at least ten requests for setup, report delivery and verification E assert 33 <= 30
